    source: KnowledgeSourceKind.Repository,
    title: 'OpenAI Codex CLI',
    url: 'https://github.com/crossmart-io/crossmart/blob/main/docs/developers/agents/codex.md',
    text: '**Status:** verified on 2026-11-06 against\nCodex docs: MCP,\nbuild skills and the\n`codex mcp` source.\n**API key header:** supported.',
